CREATE TABLE email_change_requests (user_id VARCHAR(36) PRIMARY KEY, new_email VARCHAR(254) NOT NULL, code_hash VARCHAR(64) NOT NULL, attempts INT NOT NULL DEFAULT 0, expires_at TIMESTAMP NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);

